The correct approach is an in-place sliding window using read and write pointers.

#include <iostream>
#include <vector>
using namespace std;

int removeExcess(vector<int>& timestamps) {
    int write = 0;

    for (int read = 0; read < timestamps.size(); read++) {
        if (write < 2 || timestamps[read] - timestamps[write - 2] > 5) {
            timestamps[write] = timestamps[read];
            write++;
        }
    }

    timestamps.resize(write);
    return write;
}

int main() {
    vector<int> timestamps = {1, 2, 3, 7, 8, 12};

    int count = removeExcess(timestamps);

    cout << "Remaining timestamps: ";
    for (int t : timestamps) {
        cout << t << " ";
    }

    cout << "\nCount: " << count << endl;

    return 0;
}



Complexity
- Time: O(n) — each element is processed once.
- Auxiliary space: O(1) — modification happens in place.
Why this works
- read examines every timestamp.
- write tracks the next valid position.
- timestamps[write - 2] checks the timestamp two accepted messages earlier.
- A new timestamp is retained only if it is more than five minutes after that timestamp.
Important: This treats the five-minute boundary as inclusive: three messages spanning exactly five minutes are not allowed.

